builder.Services.AddScoped<ITenantContext, TenantContext>();

public sealed class OrderService(ITenantContext tenant, IOrderRepository repo) : IOrderService
{
    public async Task<IReadOnlyList<Order>> ListAsync()
        => await repo.GetForTenantAsync(tenant.TenantId);
}

public sealed class OrderRepository(ITenantContext tenant, AppDbContext db) : IOrderRepository
{
    public Task<IReadOnlyList<Order>> GetForTenantAsync(string tenantId)
        => db.Orders.Where(o => o.TenantId == tenantId).ToListAsync();
}

// OrderService and OrderRepository share the SAME ITenantContext instance per request

// Transient: new instance every injection point
builder.Services.AddTransient<OperationIdGenerator>();

public sealed class AuditMiddleware(RequestDelegate next)
{
    public async Task InvokeAsync(
        HttpContext ctx,
        OperationIdGenerator gen1,
        OperationIdGenerator gen2)
    {
        // gen1.Id != gen2.Id — two separate transient instances
        ctx.Response.Headers["X-Op-Id"] = gen1.Id.ToString();
        await next(ctx);
    }
}

// Scoped: same instance if resolved twice in one request
