// Integration test proving scope disposal:
[Fact]
public async Task DbContext_disposed_after_request()
{
    var factory = new WebApplicationFactory<Program>();
    WeakReference? weak = null;

    await factory.WithWebHostBuilder(b => b.ConfigureServices(s =>
    {
        s.AddScoped<AppDbContext>();
    })).CreateClient().GetAsync("/api/orders");

    // After request, scoped DbContext should be eligible for GC
    // Growing ActiveDbContexts counter = captive dependency or missing disposal
